    34	extern "C" int LLVMFuzzerTestOneInput(const uint8_t* Data, size_t Size) {
    35	  assert(Data);
    36	
    37	  try {
    38	    const rawspeed::Buffer b(Data, Size);
    39	    const rawspeed::DataBuffer db(b, rawspeed::Endianness::little);
    40	    rawspeed::ByteStream bs(db);
    41	
    42	    rawspeed::RawImage mRaw(CreateRawImage(&bs));
    43	    mRaw->whitePoint = bs.getI32();
    44	
    45	    const auto offsetX = bs.getU32();
    46	    const auto offsetY = bs.getU32();
    47	    const auto width = bs.getU32();
    48	    const auto height = bs.getU32();
    49	
    50	    rawspeed::VC5Decompressor v(bs, mRaw);
    51	    mRaw->createData();
    52	    v.decode(offsetX, offsetY, width, height);
    53	
    54	    // VC5Decompressor is special
    55	    // It is expected to be the only DNG tile, and to fill the entire image.
    56	    mRaw->checkMemIsInitialized();
    57	  } catch (rawspeed::RawspeedException&) {
    58	    // Exceptions are good, crashes are bad.
    59	  }
    60	
    61	  return 0;
    62	}
